parameters.jsCode:
const today = new Date();
const followUps = [];
const stats = { total: 0, applied: 0, interviewing: 0, offered: 0, rejected: 0, ghosted: 0 };

for (const item of $input.all()) {
  const row = item.json;
  stats.total++;

  const status = (row.Status || '').toLowerCase();
  if (stats[status] !== undefined) stats[status]++;

  if (row.FollowUpDate && (row.Status === 'Applied' || row.Status === 'Interviewing')) {
    const followUpDate = new Date(row.FollowUpDate);
    const diff = Math.ceil((followUpDate - today) / (1000 * 60 * 60 * 24));

    if (diff <= 0) {
      followUps.push({
        company: row.Company,
        role: row.JobTitle,
        appliedDate: row.DateApplied,
        contactEmail: row.ContactEmail,
        daysOverdue: Math.abs(diff),
        applicationId: row.ApplicationID
      });
    }
  }
}

return [{ json: { stats, followUps, reportDate: today.toISOString() } }];

